description:
Model an anonymous pipe's rules (lesson 2.01) so they can be tested: a bounded buffer, end-of-file only when **every** writer is closed, and broken pipes.

```cpp
enum class Status { Ok, WouldBlock, EndOfFile, BrokenPipe };
struct ReadResult { Status status; std::string data; };

class Pipe
{
public:
    explicit Pipe(std::size_t capacity);
    int openWriter();
    void closeWriter(int writer);
    void closeReader();
    Status write(int writer, std::string_view data, std::size_t& accepted);
    ReadResult read(std::size_t maxBytes);
    std::size_t available() const;
};
```

- The pipe starts with **one** writer, number 0, and one reader. **openWriter** adds another writer handle (as duplicating or inheriting one does) and returns its number (1, 2, ...).
- **write** with a closed or unknown writer returns `BrokenPipe`. If the reader is closed, it also returns `BrokenPipe` and accepts nothing. Otherwise it accepts as many bytes as fit in the free space, sets `accepted`, and returns `Ok` if it accepted everything, or `WouldBlock` if some did not fit (a real pipe would block until there was room).
- **read** returns up to `maxBytes` bytes in order with `Ok`. With nothing buffered, it returns `EndOfFile` if every writer is closed, otherwise `WouldBlock`.
- **available** is the number of buffered bytes, like `PeekNamedPipe`.

starter.solution.cpp:
#include <cstddef>
#include <string>
#include <string_view>

enum class Status { Ok, WouldBlock, EndOfFile, BrokenPipe };
struct ReadResult { Status status; std::string data; };

class Pipe
{
public:
    explicit Pipe(std::size_t capacity) {}
    int openWriter() { return 0; }
    void closeWriter(int writer) {}
    void closeReader() {}
    Status write(int writer, std::string_view data, std::size_t& accepted) { accepted = data.size(); return Status::Ok; }
    ReadResult read(std::size_t maxBytes) { return { Status::EndOfFile, "" }; }
    std::size_t available() const { return 0; }
};

solution.solution.cpp:
#include <algorithm>
#include <cstddef>
#include <deque>
#include <set>
#include <string>
#include <string_view>

enum class Status { Ok, WouldBlock, EndOfFile, BrokenPipe };
struct ReadResult { Status status; std::string data; };

class Pipe
{
public:
    explicit Pipe(std::size_t capacity) : capacity{ capacity } {}

    int openWriter() { writers.insert(next); return next++; }
    void closeWriter(int writer) { writers.erase(writer); }
    void closeReader() { readerOpen = false; }

    Status write(int writer, std::string_view data, std::size_t& accepted)
    {
        accepted = 0;
        if (!writers.count(writer) || !readerOpen) return Status::BrokenPipe;
        accepted = std::min(data.size(), capacity - buffer.size());
        buffer.insert(buffer.end(), data.begin(), data.begin() + static_cast<std::ptrdiff_t>(accepted));
        return accepted == data.size() ? Status::Ok : Status::WouldBlock;
    }

    ReadResult read(std::size_t maxBytes)
    {
        if (buffer.empty()) return { writers.empty() ? Status::EndOfFile : Status::WouldBlock, "" };
        const std::size_t n{ std::min(maxBytes, buffer.size()) };
        std::string out(buffer.begin(), buffer.begin() + static_cast<std::ptrdiff_t>(n));
        buffer.erase(buffer.begin(), buffer.begin() + static_cast<std::ptrdiff_t>(n));
        return { Status::Ok, out };
    }

    std::size_t available() const { return buffer.size(); }

private:
    std::size_t capacity;
    std::deque<char> buffer;
    std::set<int> writers{ 0 };
    int next{ 1 };
    bool readerOpen{ true };
};

unitTests:
TEST("bytes in order, no boundaries") {
    Pipe p{ 64 };
    std::size_t n{};
    CHECK(p.write(0, "hello", n) == Status::Ok);
    CHECK(p.write(0, "world", n) == Status::Ok);
    CHECK_EQ(p.available(), 10u);
    const ReadResult r{ p.read(6) };
    CHECK(r.status == Status::Ok);
    CHECK_EQ(r.data, std::string("hellow"));
    CHECK_EQ(p.read(100).data, std::string("orld"));
}
TEST("a full pipe would block") {
    Pipe p{ 8 };
    std::size_t n{};
    CHECK(p.write(0, "0123456789", n) == Status::WouldBlock);
    CHECK_EQ(n, 8u);
    CHECK(p.write(0, "x", n) == Status::WouldBlock);
    CHECK_EQ(n, 0u);
    p.read(3);
    CHECK(p.write(0, "abc", n) == Status::Ok);
    CHECK_EQ(p.read(100).data, std::string("34567abc"));
}
TEST("end of file needs every writer closed") {
    Pipe p{ 16 };
    const int copy{ p.openWriter() };
    CHECK_EQ(copy, 1);
    std::size_t n{};
    p.write(0, "data", n);
    p.closeWriter(0);
    CHECK_EQ(p.read(10).data, std::string("data"));
    CHECK(p.read(10).status == Status::WouldBlock);
    p.closeWriter(copy);
    CHECK(p.read(10).status == Status::EndOfFile);
}
TEST("broken pipes") {
    Pipe p{ 16 };
    std::size_t n{ 99 };
    p.closeReader();
    CHECK(p.write(0, "lost", n) == Status::BrokenPipe);
    CHECK_EQ(n, 0u);
    Pipe q{ 16 };
    q.closeWriter(0);
    CHECK(q.write(0, "late", n) == Status::BrokenPipe);
    CHECK(q.write(7, "who", n) == Status::BrokenPipe);
}

